FROM student
WHERE user_id = #{userId}

mapper.update:
UPDATE student
student_number = #{studentNumber}, admin_class = #{adminClass}, gender = #{gender}, avatar_object_key = #{avatarObjectKey}, feature_vector = #{featureVector},
WHERE user_id = #{userId}

UPDATE student
